    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: #ffffff;
        --text: #172033;
        --muted: #5f6b7a;
        --border: #c9d3e0;
        --border-strong: #748398;
        --primary: #2457d6;
        --primary-hover: #1d46ad;
        --danger: #b42318;
        --danger-bg: #fff4f2;
        --success: #157347;
        --shadow: 0 24px 70px rgba(23, 32, 51, 0.13);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        min-height: 100vh;
        margin: 0;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(36, 87, 214, 0.18), transparent 34rem),
          linear-gradient(135deg, #eef3ff 0%, var(--bg) 48%, #ffffff 100%);
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        z-index: 10;
        transform: translateY(-200%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--primary);
        font-weight: 700;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 2rem 1rem;
      }

      .support-card {
        display: grid;
        grid-template-columns: minmax(0, 0.95fr) minmax(18rem, 1.05fr);
        width: min(62rem, 100%);
        overflow: hidden;
        border: 1px solid rgba(116, 131, 152, 0.22);
        border-radius: 2rem;
        background: var(--panel);
        box-shadow: var(--shadow);
      }

      .hero-panel {
        padding: clamp(2rem, 5vw, 4rem);
        color: #ffffff;
        background:
          linear-gradient(160deg, rgba(15, 31, 70, 0.9), rgba(36, 87, 214, 0.86)),
          linear-gradient(135deg, #0f1f46, #2457d6);
      }

      .eyebrow {
        margin: 0 0 1rem;
        color: #d6e2ff;
        font-size: 0.78rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 12ch;
        margin: 0;
        font-size: clamp(2.5rem, 6vw, 4.4rem);
        line-height: 0.95;
        letter-spacing: -0.06em;
      }

      .intro {
        max-width: 32rem;
        margin: 1.25rem 0 0;
        color: #eef3ff;
        font-size: 1.08rem;
        line-height: 1.65;
      }

      .form-panel {
        padding: clamp(1.5rem, 5vw, 3.5rem);
      }

      .required-note {
        margin: 0 0 1.5rem;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .form-field {
        margin-block-end: 1.25rem;
      }

      label {
        display: inline-block;
        margin-block-end: 0.45rem;
        font-weight: 750;
      }

      .required-marker {
        color: var(--danger);
        font-weight: 900;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        padding: 0.85rem 1rem;
        color: var(--text);
        background: #ffffff;
        font: inherit;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          background-color 160ms ease;
      }

      input:hover {
        border-color: var(--border-strong);
      }

      input:focus-visible,
      button:focus-visible {
        outline: 3px solid rgba(36, 87, 214, 0.35);
        outline-offset: 3px;
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        background: var(--danger-bg);
      }

      .helper-text,
      .error-message {
        margin: 0.45rem 0 0;
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--danger);
        font-weight: 650;
      }

      .error-message:empty {
        display: none;
      }

      .actions {
        margin-block-start: 1.75rem;
      }

      button {
        width: 100%;
        min-height: 3.25rem;
        border: 0;
        border-radius: 999px;
        padding: 0.9rem 1.25rem;
        color: #ffffff;
        background: var(--primary);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 12px 28px rgba(36, 87, 214, 0.24);
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: var(--primary-hover);
      }

      button:active {
        transform: translateY(1px);
      }

      .status-message {
        margin: 1rem 0 0;
        color: var(--success);
        font-weight: 700;
        line-height: 1.45;
      }

      .status-message:empty {
        display: none;
      }

      @media (max-width: 760px) {
        .page-shell {
          padding: 0;
        }

        .support-card {
          min-height: 100vh;
          grid-template-columns: 1fr;
          border: 0;
          border-radius: 0;
        }

        .hero-panel {
          padding-block: 2.5rem;
        }

        h1 {
          max-width: 10ch;
        }
      }

      @media (forced-colors: active) {
        body,
        .hero-panel,
        .support-card,
        input,
        button {
          forced-color-adjust: auto;
        }

        input:focus-visible,
        button:focus-visible {
          outline: 3px solid Highlight;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <div id="app"></div>
    </main>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          requiredMessage: "Error: Enter your full name."
        },
        {
          id: "email",
          name: "email",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          requiredMessage: "Error: Enter your email address.",
          patternMessage: "Error: Enter a valid email address, like name@example.com."
        },
        {
          id: "phone",
          name: "phone",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helperText: "Use 10 digits, or include a country code, for example +1 555 123 4567.",
          patternMessage: "Error: Enter a valid phone number, like +1 555 123 4567."
        }
      ];

      const state = {
        values: Object.fromEntries(fields.map((field) => [field.name, ""])),
        errors: Object.fromEntries(fields.map((field) => [field.name, ""])),
        submitted: false
      };

      function escapeHtml(value) {
        return String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#039;"
          };
          return entities[character];
        });
      }

      function isValidEmail(value) {
        return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      }

      function isValidPhone(value) {
        return /^\+?[0-9][0-9\s().-]{7,18}[0-9]$/.test(value);
      }

      function validateField(field) {
        const value = state.values[field.name].trim();

        if (field.required && !value) {
          return field.requiredMessage;
        }

        if (field.type === "email" && value && !isValidEmail(value)) {
          return field.patternMessage;
        }

        if (field.type === "tel" && value && !isValidPhone(value)) {
          return field.patternMessage;
        }

        return "";
      }

      function Field(field) {
        const errorId = `${field.id}-error`;
        const helperId = field.helperText ? `${field.id}-help` : "";
        const error = state.errors[field.name];
        const describedBy = [helperId, error ? errorId : ""].filter(Boolean).join(" ");
        const requiredMarker = field.required
          ? ' <span class="required-marker" aria-hidden="true">*</span>'
          : " <span class=\"optional-text\">(optional)</span>";

        return `
          <div class="form-field">
            <label for="${field.id}">${field.label}${requiredMarker}</label>
            <input
              id="${field.id}"
              name="${field.name}"
              type="${field.type}"
              value="${escapeHtml(state.values[field.name])}"
              autocomplete="${field.autocomplete}"
              ${field.required ? "required" : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              ${error ? `aria-invalid="true" aria-errormessage="${errorId}"` : "aria-invalid=\"false\""}
            >
            ${field.helperText ? `<p id="${helperId}" class="helper-text">${field.helperText}</p>` : ""}
            <p id="${errorId}" class="error-message">${error}</p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <div class="hero-panel">
              <p class="eyebrow">Customer support</p>
              <h1 id="support-title">How can we help?</h1>
              <p class="intro">
                Send your contact details and our support team will follow up with the next best step.
              </p>
            </div>
            <div class="form-panel">
              <p class="required-note">
                Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
              </p>
              <form id="support-form" novalidate>
                ${fields.map(Field).join("")}
                <div class="actions">
                  <button type="submit">Send request</button>
                </div>
                <p id="form-status" class="status-message" aria-live="polite">
                  ${state.submitted ? "Thanks. Your support request is ready to send." : ""}
                </p>
              </form>
            </div>
          </section>
        `;
      }

      function validateForm() {
        fields.forEach((field) => {
          state.errors[field.name] = validateField(field);
        });

        return fields.find((field) => state.errors[field.name]);
      }

      function bindFormEvents() {
        const form = document.querySelector("#support-form");

        fields.forEach((field) => {
          const input = document.getElementById(field.id);
          input.addEventListener("input", (event) => {
            state.values[field.name] = event.target.value;
            state.errors[field.name] = validateField(field);
            state.submitted = false;
            render({ focusId: field.id });
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          const firstInvalidField = validateForm();
          state.submitted = !firstInvalidField;
          render({ focusId: firstInvalidField ? firstInvalidField.id : null });
        });
      }

      function render(options = {}) {
        const app = document.getElementById("app");
        app.innerHTML = ContactForm();
        bindFormEvents();

        if (options.focusId) {
          const focusedInput = document.getElementById(options.focusId);
          focusedInput.focus();
          if (["text", "search", "tel", "url", "password"].includes(focusedInput.type)) {
            const valueLength = focusedInput.value.length;
            focusedInput.setSelectionRange(valueLength, valueLength);
          }
        }
      }

      render();
    </script>
  </body>
</html>
